{
  "name": "电动激光功率控制器",
  "name_en": "Motorized Laser Power Controller",
  "manufacturer": "",
  "description": "一种通过电动旋转机构调节光学元件角度来控制激光输出功率的装置。它通常用于在实验中连续、可重复地调节激光强度，便于进行功率扫描、光路对准和样品照射强度控制。",
  "description_en": "A device that controls laser output power by motorized rotation of an optical element. It is typically used in laboratory experiments for continuous, repeatable laser intensity adjustment, enabling power sweeps, optical alignment, and controlled sample illumination.",
  "tag_hints": [
    "laser power control",
    "motorized optical attenuator",
    "rotation-based attenuation",
    "laser intensity tuning",
    "optical alignment",
    "power sweep"
  ],
  "actions": [
    {
      "action_name": "auto-get_position",
      "description": "获取当前机械位置或旋转角度。",
      "description_en": "Get the current mechanical position or rotation angle."
    },
    {
      "action_name": "auto-execute_home_search",
      "description": "执行回零搜索，使装置返回参考原点位置。",
      "description_en": "Run a homing search to return the device to its reference home position."
    },
    {
      "action_name": "auto-get_upper_bound",
      "description": "获取可运动范围的上限位置。",
      "description_en": "Get the upper limit of the allowed motion range."
    },
    {
      "action_name": "auto-get_lower_bound",
      "description": "获取可运动范围的下限位置。",
      "description_en": "Get the lower limit of the allowed motion range."
    },
    {
      "action_name": "auto-move_abs",
      "description": "按目标激光功率百分比移动到对应的绝对位置。",
      "description_en": "Move to the absolute position corresponding to the target laser power percentage."
    },
    {
      "action_name": "auto-terminate_connection",
      "description": "断开与设备的连接。",
      "description_en": "Disconnect from the device."
    },
    {
      "action_name": "auto-unit_transformer",
      "description": "将目标功率百分比换算为对应的控制角度或位置。",
      "description_en": "Convert a target power percentage into the corresponding control angle or position."
    }
  ]
}

